INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 514, 1, '서버가 안 뜬다 (1): 데이터 디렉터리 권한', '재부팅 뒤 MariaDB 가 올라오지 않습니다. `mariadb -e "select 1"` 은 `Can''t connect to local server through socket` 오류를 냅니다. 서버를 띄우는 명령은 `nohup mysqld_safe >/dev/null 2>&1 &` 이고, 서버의 **오류 로그는 `/var/log/mysql/error.log`** 에 남습니다.

로그에서 원인을 찾아 고치고, 서버를 다시 띄워 `shop.items` 의 행 수(3)를 `/tmp/n.txt` 에 저장하세요. (값만)

(누군가 root 로 데이터 디렉터리 작업을 하다 소유자가 바뀌었다고 합니다. 데이터가 든 곳은 `/var/lib/mysql` 입니다.)', '`tail -n 20 /var/log/mysql/error.log` 로 로그 끝을 읽고, **가장 먼저 나오는 `[ERROR]` 줄**을 보세요. 파일을 쓸 수 없다는 내용이라면 파일 소유자를 확인하는 `ls -l` 이 다음 단계입니다. 서버는 `mysql` 사용자로 돌아갑니다.', 'tail -n 12 /var/log/mysql/error.log
chown -R mysql:mysql /var/lib/mysql
nohup mysqld_safe >/dev/null 2>&1 &
for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done
mariadb -N -e ''SELECT COUNT(*) FROM shop.items'' > /tmp/n.txt
cat /tmp/n.txt

# 로그의 첫 ERROR: InnoDB: The data file ''./ibdata1'' must be writable → mysql 사용자가 쓸 수 없다는 뜻. 소유자를 mysql 로 되돌리면 뜬다', '["sh", "-c", "mkdir -p /var/log/mysql; chown mysql:mysql /var/log/mysql; printf ''[mysqld_safe]\\\\nskip_syslog\\\\nlog_error=/var/log/mysql/error.log\\\\n'' > /etc/mysql/mariadb.conf.d/99-errlog.cnf; nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done; mariadb -e ''DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; USE shop; CREATE TABLE items (id INT PRIMARY KEY, name VARCHAR(20)); INSERT INTO items VALUES (1,\\"apple\\"),(2,\\"pear\\"),(3,\\"grape\\")''; mariadb-admin shutdown >/dev/null 2>&1; for i in $(seq 1 30); do mariadb-admin ping >/dev/null 2>&1 || break; sleep 0.5; done; chown -R root:root /var/lib/mysql; rm -f /var/log/mysql/error.log; nohup mysqld_safe >/dev/null 2>&1 & sleep 5; rm -f /tmp/*.txt /tmp/*.sh /tmp/*.sql /tmp/*.cnf"]', '["sh", "-c", "( for i in $(seq 1 30); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 1; done; mariadb -N -e \\"select 1\\" | grep -qx 1 ) && ( [ \\"$(stat -c %U /var/lib/mysql/ibdata1)\\" = mysql ] ) && ( [ \\"$(cat /tmp/n.txt)\\" = 3 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "서버가 응답한다", "cmd": ["sh", "-c", "for i in $(seq 1 30); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 1; done; mariadb -N -e \\"select 1\\" | grep -qx 1"]}, {"label": "데이터 파일 소유자가 mysql 이다", "cmd": ["sh", "-c", "[ \\"$(stat -c %U /var/lib/mysql/ibdata1)\\" = mysql ]"]}, {"label": "행 수를 저장했다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/n.txt)\\" = 3 ]"]}]', '[{"title": "MariaDB 오류 로그", "url": "https://mariadb.com/kb/en/error-log/"}, {"title": "SHOW REPLICA STATUS", "url": "https://mariadb.com/kb/en/show-replica-status/"}, {"title": "root 비밀번호 재설정", "url": "https://mariadb.com/kb/en/set-password/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 514 AND order_index = 1);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 514, 2, '에러 로그에서 원인이 되는 줄 찾기', '서버가 안 뜨는 상황에서 오류 로그를 열었더니 아래 줄들이 있었습니다.

```
[ERROR] InnoDB: The data file ''./ibdata1'' must be writable
[ERROR] Plugin ''InnoDB'' registration as a STORAGE ENGINE failed.
[ERROR] Could not open mysql.plugin table: "Table ''mysql.plugin'' doesn''t exist"
[ERROR] Failed to initialize plugins.
[ERROR] Aborting
```

이 중 **진짜 원인**을 가리키는 줄은 어느 것일까요?', '`[ERROR]` 가 여러 줄이면 원인과 그 여파가 섞여 있습니다. 어느 줄 하나를 고치면 나머지가 저절로 사라질지 생각해 보세요.', NULL, NULL, '[]', 'choice', '["두 번째 줄: InnoDB 플러그인 등록 실패", "마지막 줄: Aborting (서버가 중단됨)", "네 번째 줄: 플러그인 초기화 실패", "첫 번째 줄: 데이터 파일을 쓸 수 없다 (나머지는 그 여파로 이어진 오류)"]', 3, '로그는 위에서 아래로 시간순입니다. 첫 `[ERROR]` 가 가장 먼저 터진 문제이고, 뒤의 줄들은 그 때문에 연달아 실패한 결과입니다. `Aborting` 은 서버가 끝났다는 마지막 알림일 뿐 원인이 아닙니다. 그래서 로그를 읽을 때는 맨 아래가 아니라 **첫 ERROR 줄**부터 봅니다.', NULL, NULL, NULL, NULL
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 514 AND order_index = 2);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 514, 3, '서버가 안 뜬다 (2): 설정 파일의 오타', '튜닝하느라 설정 파일 `/etc/mysql/mariadb.conf.d/91-tune.cnf` 를 고친 뒤 MariaDB 가 올라오지 않습니다. 오류 로그(`/var/log/mysql/error.log`)를 읽고 원인을 고쳐 서버를 띄우세요. 서버는 `nohup mysqld_safe >/dev/null 2>&1 &` 로 띄웁니다.

의도한 설정은 **최대 접속 수 300** 입니다. 서버가 뜬 뒤 실제 `max_connections` 값이 300 이어야 합니다.', '로그의 `[ERROR]` 줄에 모르는 변수라는 뜻의 문구가 있습니다. 그 줄에 나온 이름과 설정 파일의 이름을 글자 단위로 비교하세요. 설정 파일은 `cat` 으로 봅니다.', 'tail -n 6 /var/log/mysql/error.log
cat /etc/mysql/mariadb.conf.d/91-tune.cnf
sed -i ''s/max_conections/max_connections/'' /etc/mysql/mariadb.conf.d/91-tune.cnf
nohup mysqld_safe >/dev/null 2>&1 &
for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done
mariadb -N -e ''SELECT @@max_connections''

# 로그: unknown variable ''max_conections=300''. 이름의 오타(connections)를 고치면 뜬다. 모르는 옵션이 하나라도 있으면 서버는 시작하지 않는다', '["sh", "-c", "mkdir -p /var/log/mysql; chown mysql:mysql /var/log/mysql; printf ''[mysqld_safe]\\\\nskip_syslog\\\\nlog_error=/var/log/mysql/error.log\\\\n'' > /etc/mysql/mariadb.conf.d/99-errlog.cnf; nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done; mariadb -e ''DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; USE shop; CREATE TABLE items (id INT PRIMARY KEY, name VARCHAR(20)); INSERT INTO items VALUES (1,\\"apple\\"),(2,\\"pear\\"),(3,\\"grape\\")''; mariadb-admin shutdown >/dev/null 2>&1; for i in $(seq 1 30); do mariadb-admin ping >/dev/null 2>&1 || break; sleep 0.5; done; printf ''[mysqld]\\\\nmax_allowed_packet=64M\\\\nmax_conections=300\\\\n'' > /etc/mysql/mariadb.conf.d/91-tune.cnf; rm -f /var/log/mysql/error.log; nohup mysqld_safe >/dev/null 2>&1 & sleep 5; rm -f /tmp/*.txt /tmp/*.sh /tmp/*.sql /tmp/*.cnf"]', '["sh", "-c", "( for i in $(seq 1 30); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 1; done; mariadb -N -e \\"select 1\\" | grep -qx 1 ) && ( [ \\"$(mariadb -N -e \\"SELECT @@max_connections\\")\\" = 300 ] ) && ( grep -q \\"^max_allowed_packet=64M\\" /etc/mysql/mariadb.conf.d/91-tune.cnf )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "서버가 응답한다", "cmd": ["sh", "-c", "for i in $(seq 1 30); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 1; done; mariadb -N -e \\"select 1\\" | grep -qx 1"]}, {"label": "최대 접속 수가 300 이다", "cmd": ["sh", "-c", "[ \\"$(mariadb -N -e \\"SELECT @@max_connections\\")\\" = 300 ]"]}, {"label": "다른 설정(max_allowed_packet)은 그대로다", "cmd": ["sh", "-c", "grep -q \\"^max_allowed_packet=64M\\" /etc/mysql/mariadb.conf.d/91-tune.cnf"]}]', '[{"title": "MariaDB 오류 로그", "url": "https://mariadb.com/kb/en/error-log/"}, {"title": "SHOW REPLICA STATUS", "url": "https://mariadb.com/kb/en/show-replica-status/"}, {"title": "root 비밀번호 재설정", "url": "https://mariadb.com/kb/en/set-password/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 514 AND order_index = 3);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 514, 4, 'root 비밀번호를 잃어버렸다', '운영 담당이 바뀌면서 MariaDB `root` 비밀번호를 아는 사람이 없습니다. `mariadb -e "select 1"` 은 `ERROR 1045 (28000): Access denied for user ''root''@''localhost''` 로 막힙니다. 서버를 한 번 **권한 검사 없이** 띄워 비밀번호를 바꾼 뒤, 정상으로 되돌리세요.

목표: root 의 새 비밀번호를 **`Fresh_pw_7`** 로 바꾸고, 서버는 평소처럼(권한 검사 켠 채) 떠 있어야 합니다.

(옵션 설명: `--skip-grant-tables` 는 권한 테이블 검사를 끕니다. 이 상태에서는 누구나 접속되므로 `--skip-networking` 도 함께 줘서 같은 컴퓨터에서만 접속되게 합니다.)', '서버 종료는 로그인이 필요한 `mariadb-admin` 대신, pid 파일(`/run/mysqld/mysqld.pid`)의 프로세스에 종료 신호를 보내는 방법이 있습니다. 비밀번호를 바꾸기 전에 권한 테이블을 다시 읽게 하는 `FLUSH PRIVILEGES` 가 필요합니다. 끝나면 옵션 없이 다시 띄우세요.', 'kill $(cat /run/mysqld/mysqld.pid); sleep 3
nohup mysqld_safe --skip-grant-tables --skip-networking >/dev/null 2>&1 &
sleep 4
mariadb -e "FLUSH PRIVILEGES; ALTER USER ''root''@''localhost'' IDENTIFIED BY ''Fresh_pw_7''"
kill $(cat /run/mysqld/mysqld.pid); sleep 3
nohup mysqld_safe >/dev/null 2>&1 &
for i in $(seq 1 60); do mariadb -uroot -pFresh_pw_7 -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done
mariadb -uroot -pFresh_pw_7 -N -e ''SELECT 1''

# 1) 종료  2) --skip-grant-tables 로 시작  3) FLUSH PRIVILEGES 후 ALTER USER  4) 옵션 없이 재시작. 복구 중에는 --skip-networking 으로 밖의 접속을 막는다', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done; mariadb -e ''DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; USE shop; CREATE TABLE items (id INT PRIMARY KEY, name VARCHAR(20)); INSERT INTO items VALUES (1,\\"apple\\"),(2,\\"pear\\"),(3,\\"grape\\")''; mariadb -e \\"ALTER USER ''root''@''localhost'' IDENTIFIED VIA mysql_native_password USING PASSWORD(''Forgot_it_9'')\\"; rm -f /tmp/*.txt /tmp/*.sh /tmp/*.sql /tmp/*.cnf"]', '["sh", "-c", "( for i in $(seq 1 30); do mariadb -uroot -pFresh_pw_7 -e ''select 1'' >/dev/null 2>&1 && break; sleep 1; done; mariadb -uroot -pFresh_pw_7 -N -e \\"select 1\\" | grep -qx 1 ) && ( ! tr \\"\\\\0\\" \\" \\" < /proc/$(cat /run/mysqld/mysqld.pid)/cmdline | grep -q skip-grant-tables ) && ( ! mariadb -uroot -pForgot_it_9 -e \\"select 1\\" >/dev/null 2>&1 ) && ( [ \\"$(mariadb -uroot -pFresh_pw_7 -N -e \\"SELECT COUNT(*) FROM shop.items\\")\\" = 3 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "새 비밀번호로 접속된다", "cmd": ["sh", "-c", "for i in $(seq 1 30); do mariadb -uroot -pFresh_pw_7 -e ''select 1'' >/dev/null 2>&1 && break; sleep 1; done; mariadb -uroot -pFresh_pw_7 -N -e \\"select 1\\" | grep -qx 1"]}, {"label": "권한 검사가 켜져 있다 (skip-grant-tables 로 떠 있지 않다)", "cmd": ["sh", "-c", "! tr \\"\\\\0\\" \\" \\" < /proc/$(cat /run/mysqld/mysqld.pid)/cmdline | grep -q skip-grant-tables"]}, {"label": "옛 비밀번호로는 막힌다", "cmd": ["sh", "-c", "! mariadb -uroot -pForgot_it_9 -e \\"select 1\\" >/dev/null 2>&1"]}, {"label": "데이터는 그대로다", "cmd": ["sh", "-c", "[ \\"$(mariadb -uroot -pFresh_pw_7 -N -e \\"SELECT COUNT(*) FROM shop.items\\")\\" = 3 ]"]}]', '[{"title": "MariaDB 오류 로그", "url": "https://mariadb.com/kb/en/error-log/"}, {"title": "SHOW REPLICA STATUS", "url": "https://mariadb.com/kb/en/show-replica-status/"}, {"title": "root 비밀번호 재설정", "url": "https://mariadb.com/kb/en/set-password/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 514 AND order_index = 4);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 514, 5, '비밀번호 복구용 서버 시작 옵션', 'root 비밀번호를 복구하려고 서버를 임시로 띄웁니다. 빈칸에 알맞은 옵션을 채우세요. (첫 번째: 권한 테이블 검사를 끈다 / 두 번째: 네트워크(TCP) 접속을 막아 같은 컴퓨터에서만 접속되게 한다)', '복구 중에는 누구나 비밀번호 없이 들어올 수 있는 상태입니다. 그 위험을 줄이는 옵션이 함께 필요합니다.', NULL, NULL, '[]', 'fill', '["skip-grant-tables", "skip-networking", "skip-name-resolve", "read-only", "skip-slave-start"]', NULL, '`--skip-grant-tables` 는 계정·권한 검사를 건너뛰어 비밀번호 없이 접속되게 합니다. 그 동안 외부에서 들어오지 못하도록 `--skip-networking` 으로 TCP 접속을 닫습니다. `skip-name-resolve` 는 호스트 이름 조회를 끄는 옵션이고, `read-only` 는 쓰기를 막고, `skip-slave-start` 는 복제 자동 시작을 막는 옵션이라 이 용도가 아닙니다. 복구가 끝나면 이 옵션 없이 서버를 다시 띄워야 합니다.', '[0, 1]', 'mysqld_safe --{0} --{1} &', NULL, NULL
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 514 AND order_index = 5);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 514, 6, 'root 비밀번호 복구 절차 순서', 'root 비밀번호를 잃어버렸을 때 복구하는 **순서대로** 카드를 놓으세요.', '보안 검사를 끄는 구간은 짧을수록 좋습니다. 서버를 내렸다 올리는 사이에 무엇을 하고, 끝난 뒤 무엇을 되돌려야 하는지 떠올려 보세요.', NULL, NULL, '[]', 'order', '["새 비밀번호로 접속해 확인", "옵션 없이 서버를 다시 시작", "FLUSH PRIVILEGES 후 ALTER USER 로 비밀번호 변경", "실행 중인 서버를 종료", "--skip-grant-tables --skip-networking 으로 서버 시작"]', NULL, '먼저 지금 서버를 내리고, 권한 검사를 끈 채(외부 접속은 막고) 다시 띄웁니다. 그 상태에서 FLUSH PRIVILEGES 로 권한 테이블을 읽게 한 뒤 ALTER USER 로 비밀번호를 바꿉니다. 그다음 서버를 옵션 없이 다시 띄워 보안을 되돌리고, 새 비밀번호로 접속해 확인합니다. 권한 검사를 끈 채로 두면 누구나 들어올 수 있으니 반드시 되돌려야 합니다.', '[3, 4, 2, 1, 0]', NULL, NULL, NULL
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 514 AND order_index = 6);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 514, 7, '실수로 DROP 한 표 하나만 되살리기', '개발자가 `shop.coupons` 표를 실수로 **DROP TABLE** 했습니다. 오늘 새벽에 뜬 백업이 `/root/backup/shop_full.sql`(shop 전체 덤프)에 있습니다. 그런데 백업 이후에 `orders` 에는 **새 주문(4번째)이 들어와 있어서**, 백업을 shop 에 통째로 다시 넣으면 그 주문이 사라집니다.

`coupons` 표만 되살리고(3행), `orders` 의 4행은 그대로 두세요. 작업에 쓴 임시 데이터베이스는 끝나면 지우세요.

(예: 백업을 다른 이름의 임시 DB 에 풀고, 필요한 표만 옮길 수 있습니다. 서버는 이미 떠 있습니다.)', '임시 데이터베이스를 만들고 `mariadb 임시DB < 백업파일` 로 풀면 shop 은 건드리지 않습니다. 표를 다른 DB 로 옮기는 방법은 `RENAME TABLE` 이 DB 이름을 붙여 `a.표 TO b.표` 형태를 받는다는 점을 떠올려 보세요.', 'mariadb -e ''CREATE DATABASE shop_restore''
mariadb shop_restore < /root/backup/shop_full.sql
mariadb -e ''RENAME TABLE shop_restore.coupons TO shop.coupons''
mariadb -e ''DROP DATABASE shop_restore''
mariadb -N -e ''SELECT COUNT(*) FROM shop.coupons''

# 백업을 임시 DB 에 풀면 현재 데이터를 덮어쓰지 않는다. 필요한 표만 RENAME TABLE 로 shop 으로 옮긴다', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done; mariadb -e ''DROP DATABASE IF EXISTS shop_restore; DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; USE shop; CREATE TABLE coupons (id INT PRIMARY KEY, code VARCHAR(20)); INSERT INTO coupons VALUES (1,\\"WELCOME\\"),(2,\\"SPRING\\"),(3,\\"VIP\\"); CREATE TABLE orders (id INT PRIMARY KEY, amount INT); INSERT INTO orders VALUES (1,100),(2,200),(3,300)''; mkdir -p /root/backup; mariadb-dump --single-transaction shop > /root/backup/shop_full.sql; mariadb shop -e ''INSERT INTO orders VALUES (4,400); DROP TABLE coupons''; rm -f /tmp/*.txt /tmp/*.sh /tmp/*.sql /tmp/*.cnf"]', '["sh", "-c", "( [ \\"$(mariadb -N -e \\"SELECT COUNT(*) FROM shop.coupons\\")\\" = 3 ] ) && ( [ \\"$(mariadb -N -e \\"SELECT COUNT(*) FROM shop.orders\\")\\" = 4 ] ) && ( [ -z \\"$(mariadb -N -e \\"SHOW DATABASES LIKE ''shop_restore''\\")\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "coupons 가 3행으로 돌아왔다", "cmd": ["sh", "-c", "[ \\"$(mariadb -N -e \\"SELECT COUNT(*) FROM shop.coupons\\")\\" = 3 ]"]}, {"label": "백업 이후 주문(4번째)이 그대로다", "cmd": ["sh", "-c", "[ \\"$(mariadb -N -e \\"SELECT COUNT(*) FROM shop.orders\\")\\" = 4 ]"]}, {"label": "임시 데이터베이스가 남아 있지 않다", "cmd": ["sh", "-c", "[ -z \\"$(mariadb -N -e \\"SHOW DATABASES LIKE ''shop_restore''\\")\\" ]"]}]', '[{"title": "MariaDB 오류 로그", "url": "https://mariadb.com/kb/en/error-log/"}, {"title": "SHOW REPLICA STATUS", "url": "https://mariadb.com/kb/en/show-replica-status/"}, {"title": "root 비밀번호 재설정", "url": "https://mariadb.com/kb/en/set-password/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 514 AND order_index = 7);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 514, 8, '복제가 멈췄다: 상태 읽기', '원본(3306)과 복제본(3307)이 같은 컴퓨터에서 돌고 있습니다. 모니터링에서 "복제 지연 알림"이 와서 복제본에 접속해 봅니다. (복제본 접속: `mariadb -S /tmp/r.sock`, 원본은 그냥 `mariadb`)

복제본에서 `SHOW SLAVE STATUS\\G` 를 실행해 읽고 다음을 저장하세요.

1. 복제가 멈추게 만든 **오류 번호**를 `/tmp/errno.txt` 에 (숫자만)
2. 멈춘 **스레드 이름**을 `/tmp/thread.txt` 에 (`IO` 또는 `SQL`)

(복제본에는 두 스레드가 있습니다. IO 스레드는 원본의 변경 기록(binlog)을 받아 오고, SQL 스레드는 받은 기록을 복제본에 적용합니다.)', '출력의 `Slave_IO_Running`, `Slave_SQL_Running` 이 둘 다 `Yes` 여야 정상입니다. `No` 인 쪽이 멈춘 스레드이고, 오류 번호는 같은 종류 이름(`Last_..._Errno`)의 필드에 있습니다. `\\G` 는 세로로 읽기 좋게 출력합니다. `grep` 이나 `awk` 로 필드만 뽑을 수 있습니다.', 'mariadb -S /tmp/r.sock -e ''SHOW SLAVE STATUS\\G'' | grep -E ''Running|Errno|Error:''
mariadb -S /tmp/r.sock -e ''SHOW SLAVE STATUS\\G'' | awk -F'': '' ''/^ *Last_SQL_Errno:/{print $2}'' > /tmp/errno.txt
echo SQL > /tmp/thread.txt
cat /tmp/errno.txt /tmp/thread.txt

# Slave_SQL_Running: No + Last_SQL_Errno: 1062 → SQL 스레드가 중복 키(Duplicate entry)로 멈춤. IO 스레드는 Yes 라 binlog 는 계속 받아 오는 중', '["sh", "-c", "mariadb-admin shutdown >/dev/null 2>&1; for i in $(seq 1 30); do mariadb-admin ping >/dev/null 2>&1 || break; sleep 0.5; done; mkdir -p /var/log/mysql; chown mysql:mysql /var/log/mysql; printf ''[mysqld_safe]\\\\nskip_syslog\\\\nlog_error=/var/log/mysql/error.log\\\\n'' > /etc/mysql/mariadb.conf.d/99-errlog.cnf; printf ''[mysqld]\\\\nlog_bin=/var/lib/mysql/mysql-bin\\\\nserver_id=1\\\\nbinlog_format=ROW\\\\n'' > /etc/mysql/mariadb.conf.d/99-repl.cnf; nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done; mariadb -e ''DROP DATABASE IF EXISTS shop; RESET MASTER; CREATE DATABASE shop; USE shop; CREATE TABLE items (id INT PRIMARY KEY, name VARCHAR(20)); INSERT INTO items VALUES (1,\\"apple\\"),(2,\\"pear\\"),(3,\\"grape\\"); DROP USER IF EXISTS \\"repl\\"@\\"127.0.0.1\\"; CREATE USER \\"repl\\"@\\"127.0.0.1\\" IDENTIFIED BY \\"replpw\\"; GRANT REPLICATION SLAVE ON *.* TO \\"repl\\"@\\"127.0.0.1\\"''; rm -rf /var/lib/mysql_r; mariadb-install-db --user=mysql --datadir=/var/lib/mysql_r --auth-root-authentication-method=normal >/dev/null 2>&1; printf ''[mysqld]\\\\ndatadir=/var/lib/mysql_r\\\\nport=3307\\\\nsocket=/tmp/r.sock\\\\npid-file=/tmp/r.pid\\\\nserver_id=2\\\\nbind-address=127.0.0.1\\\\nlog_error=/var/log/mysql/replica.err\\\\n'' > /etc/mysql/replica.cnf; (nohup mysqld --defaults-file=/etc/mysql/replica.cnf --user=mysql >/dev/null 2>&1 &); for i in $(seq 1 60); do mariadb -S /tmp/r.sock -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done; mariadb-dump --master-data=2 --single-transaction shop > /root/seed.dump; mariadb -S /tmp/r.sock -e ''CREATE DATABASE shop''; mariadb -S /tmp/r.sock shop < /root/seed.dump; POS=$(grep -o \\"MASTER_LOG_FILE=''[^'']*'', MASTER_LOG_POS=[0-9]*\\" /root/seed.dump); mariadb -S /tmp/r.sock -e \\"CHANGE MASTER TO MASTER_HOST=''127.0.0.1'', MASTER_PORT=3306, MASTER_USER=''repl'', MASTER_PASSWORD=''replpw'', $POS; START SLAVE\\"; rm -f /root/seed.dump; for i in $(seq 1 30); do [ \\"$(mariadb -S /tmp/r.sock -N -e ''SELECT COUNT(*) FROM shop.items'')\\" = 3 ] && break; sleep 1; done; mariadb -S /tmp/r.sock shop -e \\"INSERT INTO items VALUES (10,''local'')\\"; mariadb shop -e \\"INSERT INTO items VALUES (10,''remote''),(11,''plum'')\\"; for i in $(seq 1 30); do [ -n \\"$(mariadb -S /tmp/r.sock -e ''SHOW SLAVE STATUS\\\\G'' | awk -F'': '' ''/Last_(SQL|IO)_Errno:/&&$2!=0{print 1}'')\\" ] && break; sleep 1; done; rm -f /tmp/*.txt /tmp/*.sh /tmp/*.sql /tmp/*.cnf; rm -f /root/seed.dump"]', '["sh", "-c", "( [ \\"$(cat /tmp/errno.txt)\\" = \\"$(mariadb -S /tmp/r.sock -e ''SHOW SLAVE STATUS\\\\G'' | awk -F'': '' ''/^ *Last_SQL_Errno:/{print $2}'')\\" ] ) && ( [ \\"$(cat /tmp/errno.txt)\\" = 1062 ] ) && ( [ \\"$(cat /tmp/thread.txt)\\" = SQL ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "오류 번호가 맞다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/errno.txt)\\" = \\"$(mariadb -S /tmp/r.sock -e ''SHOW SLAVE STATUS\\\\G'' | awk -F'': '' ''/^ *Last_SQL_Errno:/{print $2}'')\\" ]"]}, {"label": "1062 이다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/errno.txt)\\" = 1062 ]"]}, {"label": "멈춘 스레드는 SQL 이다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/thread.txt)\\" = SQL ]"]}]', '[{"title": "MariaDB 오류 로그", "url": "https://mariadb.com/kb/en/error-log/"}, {"title": "SHOW REPLICA STATUS", "url": "https://mariadb.com/kb/en/show-replica-status/"}, {"title": "root 비밀번호 재설정", "url": "https://mariadb.com/kb/en/set-password/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 514 AND order_index = 8);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 514, 9, '복제 IO 오류: 원본 계정 비밀번호가 바뀌었다', '복제본의 IO 스레드가 원본에 붙지 못합니다. (복제본 접속: `mariadb -S /tmp/r.sock`) 복제본에서 `SHOW SLAVE STATUS\\G` 를 보면 `Last_IO_Errno: 1045` 와 `Access denied for user ''repl''` 메시지가 있습니다. 원본 관리자가 복제용 계정 `repl` 의 비밀번호를 **`Repl2026pw`** 로 바꿨는데 복제본의 설정에는 옛 비밀번호가 남아 있습니다.

복제본의 설정을 새 비밀번호로 고치고 복제를 다시 시작해, 복제본에도 원본의 `melon`(id 4)이 반영되게 하세요.', '복제를 멈추고, 원본 접속 정보만 새 비밀번호로 바꾸고(나머지 정보는 그대로 둡니다), 복제를 다시 시작하는 순서입니다. 접속 정보를 바꾸는 명령은 복제를 설정할 때 쓰는 그 명령입니다. 다시 시작한 뒤 상태 필드로 확인하세요.', 'mariadb -S /tmp/r.sock -e "STOP SLAVE; CHANGE MASTER TO MASTER_PASSWORD=''Repl2026pw''; START SLAVE"
sleep 2
mariadb -S /tmp/r.sock -e ''SHOW SLAVE STATUS\\G'' | grep -E ''Running|Errno''
mariadb -S /tmp/r.sock -N -e ''SELECT name FROM shop.items WHERE id=4''

# 1045 은 인증 실패. 접속 정보(MASTER_PASSWORD)만 바꾸면 복제 위치는 그대로라, 멈춰 있던 동안의 변경(melon)을 이어서 받아 온다', '["sh", "-c", "mariadb-admin shutdown >/dev/null 2>&1; for i in $(seq 1 30); do mariadb-admin ping >/dev/null 2>&1 || break; sleep 0.5; done; mkdir -p /var/log/mysql; chown mysql:mysql /var/log/mysql; printf ''[mysqld_safe]\\\\nskip_syslog\\\\nlog_error=/var/log/mysql/error.log\\\\n'' > /etc/mysql/mariadb.conf.d/99-errlog.cnf; printf ''[mysqld]\\\\nlog_bin=/var/lib/mysql/mysql-bin\\\\nserver_id=1\\\\nbinlog_format=ROW\\\\n'' > /etc/mysql/mariadb.conf.d/99-repl.cnf; nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done; mariadb -e ''DROP DATABASE IF EXISTS shop; RESET MASTER; CREATE DATABASE shop; USE shop; CREATE TABLE items (id INT PRIMARY KEY, name VARCHAR(20)); INSERT INTO items VALUES (1,\\"apple\\"),(2,\\"pear\\"),(3,\\"grape\\"); DROP USER IF EXISTS \\"repl\\"@\\"127.0.0.1\\"; CREATE USER \\"repl\\"@\\"127.0.0.1\\" IDENTIFIED BY \\"replpw\\"; GRANT REPLICATION SLAVE ON *.* TO \\"repl\\"@\\"127.0.0.1\\"''; rm -rf /var/lib/mysql_r; mariadb-install-db --user=mysql --datadir=/var/lib/mysql_r --auth-root-authentication-method=normal >/dev/null 2>&1; printf ''[mysqld]\\\\ndatadir=/var/lib/mysql_r\\\\nport=3307\\\\nsocket=/tmp/r.sock\\\\npid-file=/tmp/r.pid\\\\nserver_id=2\\\\nbind-address=127.0.0.1\\\\nlog_error=/var/log/mysql/replica.err\\\\n'' > /etc/mysql/replica.cnf; (nohup mysqld --defaults-file=/etc/mysql/replica.cnf --user=mysql >/dev/null 2>&1 &); for i in $(seq 1 60); do mariadb -S /tmp/r.sock -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done; mariadb-dump --master-data=2 --single-transaction shop > /root/seed.dump; mariadb -S /tmp/r.sock -e ''CREATE DATABASE shop''; mariadb -S /tmp/r.sock shop < /root/seed.dump; POS=$(grep -o \\"MASTER_LOG_FILE=''[^'']*'', MASTER_LOG_POS=[0-9]*\\" /root/seed.dump); mariadb -S /tmp/r.sock -e \\"CHANGE MASTER TO MASTER_HOST=''127.0.0.1'', MASTER_PORT=3306, MASTER_USER=''repl'', MASTER_PASSWORD=''replpw'', $POS; START SLAVE\\"; rm -f /root/seed.dump; for i in $(seq 1 30); do [ \\"$(mariadb -S /tmp/r.sock -N -e ''SELECT COUNT(*) FROM shop.items'')\\" = 3 ] && break; sleep 1; done; mariadb -S /tmp/r.sock -e ''STOP SLAVE''; mariadb -e \\"SET sql_log_bin=0; SET PASSWORD FOR ''repl''@''127.0.0.1'' = PASSWORD(''Repl2026pw'')\\"; mariadb shop -e \\"INSERT INTO items VALUES (4,''melon'')\\"; mariadb -S /tmp/r.sock -e ''START SLAVE''; for i in $(seq 1 30); do [ -n \\"$(mariadb -S /tmp/r.sock -e ''SHOW SLAVE STATUS\\\\G'' | awk -F'': '' ''/Last_(SQL|IO)_Errno:/&&$2!=0{print 1}'')\\" ] && break; sleep 1; done; rm -f /tmp/*.txt /tmp/*.sh /tmp/*.sql /tmp/*.cnf; rm -f /root/seed.dump"]', '["sh", "-c", "( for i in $(seq 1 20); do [ \\"$(mariadb -S /tmp/r.sock -e ''SHOW SLAVE STATUS\\\\G'' | awk -F'': '' ''/^ *Slave_IO_Running:/{print $2}'')\\" = Yes ] && break; sleep 1; done; [ \\"$(mariadb -S /tmp/r.sock -e ''SHOW SLAVE STATUS\\\\G'' | awk -F'': '' ''/^ *Slave_IO_Running:/{print $2}'')\\" = Yes ] ) && ( [ \\"$(mariadb -S /tmp/r.sock -e ''SHOW SLAVE STATUS\\\\G'' | awk -F'': '' ''/^ *Slave_SQL_Running:/{print $2}'')\\" = Yes ] ) && ( for i in $(seq 1 20); do [ \\"$(mariadb -S /tmp/r.sock -N -e \\"SELECT name FROM shop.items WHERE id=4\\")\\" = melon ] && break; sleep 1; done; [ \\"$(mariadb -S /tmp/r.sock -N -e \\"SELECT name FROM shop.items WHERE id=4\\")\\" = melon ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "IO 스레드가 돈다", "cmd": ["sh", "-c", "for i in $(seq 1 20); do [ \\"$(mariadb -S /tmp/r.sock -e ''SHOW SLAVE STATUS\\\\G'' | awk -F'': '' ''/^ *Slave_IO_Running:/{print $2}'')\\" = Yes ] && break; sleep 1; done; [ \\"$(mariadb -S /tmp/r.sock -e ''SHOW SLAVE STATUS\\\\G'' | awk -F'': '' ''/^ *Slave_IO_Running:/{print $2}'')\\" = Yes ]"]}, {"label": "SQL 스레드가 돈다", "cmd": ["sh", "-c", "[ \\"$(mariadb -S /tmp/r.sock -e ''SHOW SLAVE STATUS\\\\G'' | awk -F'': '' ''/^ *Slave_SQL_Running:/{print $2}'')\\" = Yes ]"]}, {"label": "복제본에 melon 이 반영됐다", "cmd": ["sh", "-c", "for i in $(seq 1 20); do [ \\"$(mariadb -S /tmp/r.sock -N -e \\"SELECT name FROM shop.items WHERE id=4\\")\\" = melon ] && break; sleep 1; done; [ \\"$(mariadb -S /tmp/r.sock -N -e \\"SELECT name FROM shop.items WHERE id=4\\")\\" = melon ]"]}]', '[{"title": "MariaDB 오류 로그", "url": "https://mariadb.com/kb/en/error-log/"}, {"title": "SHOW REPLICA STATUS", "url": "https://mariadb.com/kb/en/show-replica-status/"}, {"title": "root 비밀번호 재설정", "url": "https://mariadb.com/kb/en/set-password/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 514 AND order_index = 9);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 514, 10, '1062 와 1032 는 무엇이 다른가', '복제 중단 오류 두 가지를 비교합니다. 원본에서 일어난 변경을 복제본이 따라 하다 멈췄을 때, 오류 번호가 말해 주는 **복제본의 상태**로 맞는 것은 어느 것일까요?', '`1062` 는 `Duplicate entry`, `1032` 는 `Can''t find record` 라는 영어 메시지로 나옵니다. 각 메시지가 "복제본의 데이터가 어떤 상태일 때" 나올 말인지 풀어 보세요.', NULL, NULL, '[]', 'choice', '["1062 는 복제본의 디스크가 가득 찼다는 뜻, 1032 는 원본과 연결이 끊겼다는 뜻", "1062 는 비밀번호가 틀렸다는 뜻, 1032 는 포트가 막혔다는 뜻", "둘 다 복제본이 원본보다 느리다는 뜻이다", "1062 는 복제본에 같은 키의 행이 이미 있다는 뜻, 1032 는 고칠·지울 행이 복제본에 없다는 뜻"]', 3, '둘 다 SQL 스레드(적용 쪽)에서 나는 "데이터가 서로 달라서" 생기는 오류입니다. 1062(Duplicate entry)는 INSERT 하려는 키가 복제본에 이미 있을 때, 1032(Can''t find record)는 UPDATE·DELETE 하려는 행이 복제본에 없을 때입니다. 보통 복제본에 누가 직접 쓰기를 했거나 처음 복제본을 맞출 때 어긋난 것이 원인입니다. 연결·인증 문제는 IO 스레드 오류(1045 등)이고, 느린 것은 오류가 아니라 지연(Seconds_Behind_Master)입니다.', NULL, NULL, NULL, NULL
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 514 AND order_index = 10);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 514, 11, '복제 1062: 복제본에 있는 충돌 행 정리', '복제본의 SQL 스레드가 멈췄습니다. (복제본 접속: `mariadb -S /tmp/r.sock`) `Last_SQL_Errno: 1062` 와 `Duplicate entry ''10'' for key ''PRIMARY''` 입니다. 확인해 보니 복제본에서 누가 직접 `items` 에 id 10 행(`local`)을 넣어 둔 상태에서, 원본이 같은 id 10 행(`remote`)을 넣으려다 부딪혔습니다. **원본의 데이터가 맞습니다.**

복제본을 고쳐 복제가 다시 돌게 하고, 복제본의 `items` 가 원본과 같아지게(id 10 은 `remote`, id 11 `plum` 포함) 하세요.', '멈춘 이벤트는 한 번 실패한 채 대기 중이라, 막고 있는 원인(복제본에 먼저 있는 행)을 치우고 SQL 스레드를 다시 시작하면 그 이벤트를 다시 시도합니다. 건너뛰기(skip)는 원본의 변경을 버리는 것이라 이 경우 맞지 않습니다. 어느 행이 충돌인지는 오류 메시지의 키 값입니다.', 'mariadb -S /tmp/r.sock -e ''SHOW SLAVE STATUS\\G'' | grep -E ''Last_SQL_Err''
mariadb -S /tmp/r.sock shop -e "SELECT * FROM items WHERE id=10"
mariadb -S /tmp/r.sock shop -e "DELETE FROM items WHERE id=10"
mariadb -S /tmp/r.sock -e ''START SLAVE''
sleep 2
mariadb -S /tmp/r.sock -e ''SELECT * FROM shop.items''

# 복제본에 직접 들어간 행이 충돌의 원인. 지우고 START SLAVE 하면 멈춘 이벤트(remote)와 뒤의 이벤트(plum)가 차례로 적용된다', '["sh", "-c", "mariadb-admin shutdown >/dev/null 2>&1; for i in $(seq 1 30); do mariadb-admin ping >/dev/null 2>&1 || break; sleep 0.5; done; mkdir -p /var/log/mysql; chown mysql:mysql /var/log/mysql; printf ''[mysqld_safe]\\\\nskip_syslog\\\\nlog_error=/var/log/mysql/error.log\\\\n'' > /etc/mysql/mariadb.conf.d/99-errlog.cnf; printf ''[mysqld]\\\\nlog_bin=/var/lib/mysql/mysql-bin\\\\nserver_id=1\\\\nbinlog_format=ROW\\\\n'' > /etc/mysql/mariadb.conf.d/99-repl.cnf; nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done; mariadb -e ''DROP DATABASE IF EXISTS shop; RESET MASTER; CREATE DATABASE shop; USE shop; CREATE TABLE items (id INT PRIMARY KEY, name VARCHAR(20)); INSERT INTO items VALUES (1,\\"apple\\"),(2,\\"pear\\"),(3,\\"grape\\"); DROP USER IF EXISTS \\"repl\\"@\\"127.0.0.1\\"; CREATE USER \\"repl\\"@\\"127.0.0.1\\" IDENTIFIED BY \\"replpw\\"; GRANT REPLICATION SLAVE ON *.* TO \\"repl\\"@\\"127.0.0.1\\"''; rm -rf /var/lib/mysql_r; mariadb-install-db --user=mysql --datadir=/var/lib/mysql_r --auth-root-authentication-method=normal >/dev/null 2>&1; printf ''[mysqld]\\\\ndatadir=/var/lib/mysql_r\\\\nport=3307\\\\nsocket=/tmp/r.sock\\\\npid-file=/tmp/r.pid\\\\nserver_id=2\\\\nbind-address=127.0.0.1\\\\nlog_error=/var/log/mysql/replica.err\\\\n'' > /etc/mysql/replica.cnf; (nohup mysqld --defaults-file=/etc/mysql/replica.cnf --user=mysql >/dev/null 2>&1 &); for i in $(seq 1 60); do mariadb -S /tmp/r.sock -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done; mariadb-dump --master-data=2 --single-transaction shop > /root/seed.dump; mariadb -S /tmp/r.sock -e ''CREATE DATABASE shop''; mariadb -S /tmp/r.sock shop < /root/seed.dump; POS=$(grep -o \\"MASTER_LOG_FILE=''[^'']*'', MASTER_LOG_POS=[0-9]*\\" /root/seed.dump); mariadb -S /tmp/r.sock -e \\"CHANGE MASTER TO MASTER_HOST=''127.0.0.1'', MASTER_PORT=3306, MASTER_USER=''repl'', MASTER_PASSWORD=''replpw'', $POS; START SLAVE\\"; rm -f /root/seed.dump; for i in $(seq 1 30); do [ \\"$(mariadb -S /tmp/r.sock -N -e ''SELECT COUNT(*) FROM shop.items'')\\" = 3 ] && break; sleep 1; done; mariadb -S /tmp/r.sock shop -e \\"INSERT INTO items VALUES (10,''local'')\\"; mariadb shop -e \\"INSERT INTO items VALUES (10,''remote''),(11,''plum'')\\"; for i in $(seq 1 30); do [ -n \\"$(mariadb -S /tmp/r.sock -e ''SHOW SLAVE STATUS\\\\G'' | awk -F'': '' ''/Last_(SQL|IO)_Errno:/&&$2!=0{print 1}'')\\" ] && break; sleep 1; done; rm -f /tmp/*.txt /tmp/*.sh /tmp/*.sql /tmp/*.cnf; rm -f /root/seed.dump"]', '["sh", "-c", "( for i in $(seq 1 20); do [ \\"$(mariadb -S /tmp/r.sock -e ''SHOW SLAVE STATUS\\\\G'' | awk -F'': '' ''/^ *Slave_SQL_Running:/{print $2}'')\\" = Yes ] && break; sleep 1; done; [ \\"$(mariadb -S /tmp/r.sock -e ''SHOW SLAVE STATUS\\\\G'' | awk -F'': '' ''/^ *Slave_SQL_Running:/{print $2}'')\\" = Yes ] ) && ( for i in $(seq 1 20); do [ \\"$(mariadb -S /tmp/r.sock -N -e \\"SELECT name FROM shop.items WHERE id=10\\")\\" = remote ] && break; sleep 1; done; [ \\"$(mariadb -S /tmp/r.sock -N -e \\"SELECT name FROM shop.items WHERE id=10\\")\\" = remote ] ) && ( sleep 1; [ \\"$(mariadb -N -e \\"CHECKSUM TABLE shop.items\\")\\" = \\"$(mariadb -S /tmp/r.sock -N -e \\"CHECKSUM TABLE shop.items\\")\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "SQL 스레드가 돈다", "cmd": ["sh", "-c", "for i in $(seq 1 20); do [ \\"$(mariadb -S /tmp/r.sock -e ''SHOW SLAVE STATUS\\\\G'' | awk -F'': '' ''/^ *Slave_SQL_Running:/{print $2}'')\\" = Yes ] && break; sleep 1; done; [ \\"$(mariadb -S /tmp/r.sock -e ''SHOW SLAVE STATUS\\\\G'' | awk -F'': '' ''/^ *Slave_SQL_Running:/{print $2}'')\\" = Yes ]"]}, {"label": "id 10 이 원본 값(remote)이다", "cmd": ["sh", "-c", "for i in $(seq 1 20); do [ \\"$(mariadb -S /tmp/r.sock -N -e \\"SELECT name FROM shop.items WHERE id=10\\")\\" = remote ] && break; sleep 1; done; [ \\"$(mariadb -S /tmp/r.sock -N -e \\"SELECT name FROM shop.items WHERE id=10\\")\\" = remote ]"]}, {"label": "복제본이 원본과 같다", "cmd": ["sh", "-c", "sleep 1; [ \\"$(mariadb -N -e \\"CHECKSUM TABLE shop.items\\")\\" = \\"$(mariadb -S /tmp/r.sock -N -e \\"CHECKSUM TABLE shop.items\\")\\" ]"]}]', '[{"title": "MariaDB 오류 로그", "url": "https://mariadb.com/kb/en/error-log/"}, {"title": "SHOW REPLICA STATUS", "url": "https://mariadb.com/kb/en/show-replica-status/"}, {"title": "root 비밀번호 재설정", "url": "https://mariadb.com/kb/en/set-password/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 514 AND order_index = 11);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 514, 12, '복제 1032: 이미 없는 행을 지우려다 멈췄다', '복제본의 SQL 스레드가 멈췄습니다. (복제본 접속: `mariadb -S /tmp/r.sock`) `Last_SQL_Errno: 1032` 와 `Can''t find record in ''items''` 입니다. 원본이 `items` 의 id 2 행을 DELETE 했는데, 복제본에는 **이미 그 행이 없어서**(누가 먼저 지움) 지울 수 없다는 뜻입니다. 결과적으로 양쪽 모두 id 2 가 없는 상태가 되길 원하니, 이 DELETE 한 건만 **건너뛰어도** 데이터는 같아집니다. 이 뒤에 원본이 `after`(id 4)를 추가한 변경도 있습니다.

문제의 이벤트 하나만 건너뛰고 복제를 재개해, 복제본이 원본과 같아지게(id 4 포함) 하세요.', '복제를 멈춘 상태에서 "다음에 건너뛸 이벤트 그룹 수"를 정하는 서버 변수를 쓰고 다시 시작합니다. 건너뛴 뒤에는 상태 필드와 두 서버의 `items` 를 비교해 같은지 확인하세요.', 'mariadb -S /tmp/r.sock -e ''SHOW SLAVE STATUS\\G'' | grep -E ''Last_SQL_Err''
mariadb -S /tmp/r.sock -e ''STOP SLAVE; SET GLOBAL sql_slave_skip_counter=1; START SLAVE''
sleep 2
mariadb -S /tmp/r.sock -e ''SELECT * FROM shop.items''

# 건너뛰기는 그 변경을 영영 적용하지 않는 것이다. 이번처럼 양쪽 결과가 이미 같다는 것을 확인한 뒤에만 쓴다. 뒤의 변경(after)은 정상 적용된다', '["sh", "-c", "mariadb-admin shutdown >/dev/null 2>&1; for i in $(seq 1 30); do mariadb-admin ping >/dev/null 2>&1 || break; sleep 0.5; done; mkdir -p /var/log/mysql; chown mysql:mysql /var/log/mysql; printf ''[mysqld_safe]\\\\nskip_syslog\\\\nlog_error=/var/log/mysql/error.log\\\\n'' > /etc/mysql/mariadb.conf.d/99-errlog.cnf; printf ''[mysqld]\\\\nlog_bin=/var/lib/mysql/mysql-bin\\\\nserver_id=1\\\\nbinlog_format=ROW\\\\n'' > /etc/mysql/mariadb.conf.d/99-repl.cnf; nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done; mariadb -e ''DROP DATABASE IF EXISTS shop; RESET MASTER; CREATE DATABASE shop; USE shop; CREATE TABLE items (id INT PRIMARY KEY, name VARCHAR(20)); INSERT INTO items VALUES (1,\\"apple\\"),(2,\\"pear\\"),(3,\\"grape\\"); DROP USER IF EXISTS \\"repl\\"@\\"127.0.0.1\\"; CREATE USER \\"repl\\"@\\"127.0.0.1\\" IDENTIFIED BY \\"replpw\\"; GRANT REPLICATION SLAVE ON *.* TO \\"repl\\"@\\"127.0.0.1\\"''; rm -rf /var/lib/mysql_r; mariadb-install-db --user=mysql --datadir=/var/lib/mysql_r --auth-root-authentication-method=normal >/dev/null 2>&1; printf ''[mysqld]\\\\ndatadir=/var/lib/mysql_r\\\\nport=3307\\\\nsocket=/tmp/r.sock\\\\npid-file=/tmp/r.pid\\\\nserver_id=2\\\\nbind-address=127.0.0.1\\\\nlog_error=/var/log/mysql/replica.err\\\\n'' > /etc/mysql/replica.cnf; (nohup mysqld --defaults-file=/etc/mysql/replica.cnf --user=mysql >/dev/null 2>&1 &); for i in $(seq 1 60); do mariadb -S /tmp/r.sock -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done; mariadb-dump --master-data=2 --single-transaction shop > /root/seed.dump; mariadb -S /tmp/r.sock -e ''CREATE DATABASE shop''; mariadb -S /tmp/r.sock shop < /root/seed.dump; POS=$(grep -o \\"MASTER_LOG_FILE=''[^'']*'', MASTER_LOG_POS=[0-9]*\\" /root/seed.dump); mariadb -S /tmp/r.sock -e \\"CHANGE MASTER TO MASTER_HOST=''127.0.0.1'', MASTER_PORT=3306, MASTER_USER=''repl'', MASTER_PASSWORD=''replpw'', $POS; START SLAVE\\"; rm -f /root/seed.dump; for i in $(seq 1 30); do [ \\"$(mariadb -S /tmp/r.sock -N -e ''SELECT COUNT(*) FROM shop.items'')\\" = 3 ] && break; sleep 1; done; mariadb -S /tmp/r.sock shop -e ''DELETE FROM items WHERE id=2''; mariadb shop -e \\"DELETE FROM items WHERE id=2; INSERT INTO items VALUES (4,''after'')\\"; for i in $(seq 1 30); do [ -n \\"$(mariadb -S /tmp/r.sock -e ''SHOW SLAVE STATUS\\\\G'' | awk -F'': '' ''/Last_(SQL|IO)_Errno:/&&$2!=0{print 1}'')\\" ] && break; sleep 1; done; rm -f /tmp/*.txt /tmp/*.sh /tmp/*.sql /tmp/*.cnf; rm -f /root/seed.dump"]', '["sh", "-c", "( for i in $(seq 1 20); do [ \\"$(mariadb -S /tmp/r.sock -e ''SHOW SLAVE STATUS\\\\G'' | awk -F'': '' ''/^ *Slave_SQL_Running:/{print $2}'')\\" = Yes ] && break; sleep 1; done; [ \\"$(mariadb -S /tmp/r.sock -e ''SHOW SLAVE STATUS\\\\G'' | awk -F'': '' ''/^ *Slave_SQL_Running:/{print $2}'')\\" = Yes ] ) && ( for i in $(seq 1 20); do [ \\"$(mariadb -S /tmp/r.sock -N -e \\"SELECT name FROM shop.items WHERE id=4\\")\\" = after ] && break; sleep 1; done; [ \\"$(mariadb -S /tmp/r.sock -N -e \\"SELECT name FROM shop.items WHERE id=4\\")\\" = after ] ) && ( sleep 1; [ \\"$(mariadb -N -e \\"CHECKSUM TABLE shop.items\\")\\" = \\"$(mariadb -S /tmp/r.sock -N -e \\"CHECKSUM TABLE shop.items\\")\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "SQL 스레드가 돈다", "cmd": ["sh", "-c", "for i in $(seq 1 20); do [ \\"$(mariadb -S /tmp/r.sock -e ''SHOW SLAVE STATUS\\\\G'' | awk -F'': '' ''/^ *Slave_SQL_Running:/{print $2}'')\\" = Yes ] && break; sleep 1; done; [ \\"$(mariadb -S /tmp/r.sock -e ''SHOW SLAVE STATUS\\\\G'' | awk -F'': '' ''/^ *Slave_SQL_Running:/{print $2}'')\\" = Yes ]"]}, {"label": "멈춘 뒤의 변경(after)도 반영됐다", "cmd": ["sh", "-c", "for i in $(seq 1 20); do [ \\"$(mariadb -S /tmp/r.sock -N -e \\"SELECT name FROM shop.items WHERE id=4\\")\\" = after ] && break; sleep 1; done; [ \\"$(mariadb -S /tmp/r.sock -N -e \\"SELECT name FROM shop.items WHERE id=4\\")\\" = after ]"]}, {"label": "복제본이 원본과 같다", "cmd": ["sh", "-c", "sleep 1; [ \\"$(mariadb -N -e \\"CHECKSUM TABLE shop.items\\")\\" = \\"$(mariadb -S /tmp/r.sock -N -e \\"CHECKSUM TABLE shop.items\\")\\" ]"]}]', '[{"title": "MariaDB 오류 로그", "url": "https://mariadb.com/kb/en/error-log/"}, {"title": "SHOW REPLICA STATUS", "url": "https://mariadb.com/kb/en/show-replica-status/"}, {"title": "root 비밀번호 재설정", "url": "https://mariadb.com/kb/en/set-password/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 514 AND order_index = 12);
